from strands import Agent
from strands.session import FileSessionManager

SESSION_DIR = "./sessions"
SESSION_ID = "demo"

# File-backed session manager for session 'demo'
session_manager = FileSessionManager(base_dir=SESSION_DIR, session_id=SESSION_ID)

class DemoAgent(Agent):
    def __init__(self, *args, **kwargs):
        super(DemoAgent, self).__init__(*args, **kwargs)
        # Attach the file-backed session manager
        self.session = session_manager

    def on_start(self):
        # Optional: load existing session data if available
        if hasattr(self.session, "load"):
            self.session.load()

    def on_stop(self):
        # Optional: persist session data on shutdown
        if hasattr(self.session, "save"):
            self.session.save()

if __name__ == "__main__":
    a = DemoAgent("demo_agent")
    a.run()

Note: This sets up a file-backed session persistence using FileSessionManager, storing per-session data under ./sessions for the session id "demo".

from strands import FileSessionManager, Agent

class DemoAgent(Agent):
    def __init__(self, session_manager=None, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.session_manager = session_manager or FileSessionManager(base_dir="./sessions")

    def respond(self, message, session_id="demo"):
        session = self.session_manager.get_session(session_id)
        if session is None:
            session = {"messages": []}
        session["messages"].append({"from": "user", "text": message})
        response = f"Echo: {message}"
        session["messages"].append({"from": "agent", "text": response})
        self.session_manager.save_session(session_id, session)
        return response

def main():
    sm = FileSessionManager(base_dir="./sessions")
    agent = DemoAgent(session_manager=sm)
    print("Talking to session 'demo'. Type 'exit' to quit.")
    while True:
        user = input("You: ")
        if user.strip().lower() in ("exit","quit"):
            break
        print("Bot:", agent.respond(user, session_id="demo"))

if __name__ == "__main__":
    main()

Note: This wires a FileSessionManager into an Agent. The conversation for session_id 'demo' is saved to disk, so restarting the script will load the previous session and continue the conversation.

