from strands.multiagent import Swarm

class Coder:
    def __init__(self, name="coder"):
        self.name = name

    def act(self, task):
        # If not yet coded, perform coding
        if not getattr(task, "coded", False):
            task.coded = True
            task.log.append(f"{self.name} coded the task")

class Reviewer:
    def __init__(self, name="reviewer"):
        self.name = name

    def act(self, task):
        # If coded but not yet reviewed, perform review
        if getattr(task, "coded", False) and not getattr(task, "reviewed", False):
            task.reviewed = True
            task.log.append(f"{self.name} reviewed the code")

class Task:
    def __init__(self, description):
        self.description = description
        self.coded = False
        self.reviewed = False
        self.log = []

def main():
    # Create a single task
    t = Task("One feature task")

    # Create two agents: a coder and a reviewer
    coder = Coder("coder")
    reviewer = Reviewer("reviewer")

    # Build a Swarm with the two agents
    swarm = Swarm([coder, reviewer])

    # Run the swarm on one task
    swarm.run(t)

    # Optional: print results
    print("Task:", t.description)
    print("Coded:", t.coded, "Reviewed:", t.reviewed)
    print("Logs:")
    for line in t.log:
        print("-", line)

if __name__ == "__main__":
    main()

