from strands.multiagent import Swarm, Agent

class Researcher(Agent):
    def setup(self):
        self.sent = False

    def step(self, *args, **kwargs):
        if not self.sent:
            self.sent = True
            # send a message to the writer
            self.send("writer", {"type": "request", "content": "Please write a note about agent-based systems."})

class Writer(Agent):
    def setup(self):
        self.received = []

    def step(self, *args, **kwargs):
        msg = self.receive("researcher")
        if msg:
            self.received.append(msg)
            # Persist the produced content
            with open("out.txt", "a") as f:
                f.write(f"Writer received: {msg}\n")
            # acknowledge
            self.send("researcher", {"type": "response", "content": "written"})

swarm = Swarm([Researcher(name="researcher"), Writer(name="writer")], name="minimal_swarm")
swarm.run()
```

