import asyncio

# Try to import the Strands tool decorator; provide a fallback if not available in this env.
try:
    from strands.core import tool
except Exception:
    def tool(func):
        return func

@tool
def run_async(obj, *args, **kwargs):
    """
    Strands tool to run an async coroutine using the current event loop's run_until_complete.

    - If obj is a coroutine object, it will be awaited.
    - If obj is a callable, it will be called with (args, kwargs) to obtain a coroutine.
    """
    if asyncio.iscoroutine(obj):
        coro = obj
    elif callable(obj):
        coro = obj(*args, **kwargs)
    else:
        raise TypeError("First argument must be a coroutine or a callable returning a coroutine.")
    loop = asyncio.get_event_loop()
    return loop.run_until_complete(coro)

