from strands import tool
import asyncio
from typing import Any

@tool
def run_async_sync(target: Any, *args, **kwargs) -> Any:
    """
    Strands tool: Run an async coroutine on the current event loop using run_until_complete.
    - If target is a coroutine object or Future, it is awaited directly.
    - If target is a callable, it is invoked with (args, kwargs) to obtain a coroutine.
    This allows agent code (which is typically synchronous) to invoke async routines.
    """
    if asyncio.iscoroutine(target) or isinstance(target, asyncio.Future):
        coro = target
    elif callable(target):
        coro = target(*args, **kwargs)
    else:
        raise TypeError("Target must be a coroutine, coroutine object, or a callable returning a coroutine.")

    loop = asyncio.get_event_loop()
    if loop.is_running():
        new_loop = asyncio.new_event_loop()
        return new_loop.run_until_complete(coro)
    else:
        return loop.run_until_complete(coro)

Note: This tool bridges async coroutines to Strands agent code by running them synchronously on the event loop. If you call it from within a running loop context, it creates a new loop to avoid interfering with the active loop.

from strands import tool
import asyncio

@tool
def run_async(coro_or_callable, *args, **kwargs):
    """
    Strands tool: execute an async coroutine or coroutine factory synchronously using the event loop.
    - If coro_or_callable is an already-created coroutine, it will be awaited.
    - If it's a callable, it will be invoked with (args, kwargs) to create a coroutine.
    Returns the result of the coroutine.
    """
    try:
        loop = asyncio.get_event_loop()
    except RuntimeError:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

    if asyncio.iscoroutine(coro_or_callable):
        coro = coro_or_callable
    elif callable(coro_or_callable):
        coro = coro_or_callable(*args, **kwargs)
    else:
        raise TypeError("First argument must be a coroutine or a coroutine function")

    if loop.is_closed():
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

    return loop.run_until_complete(coro)

Note: This tool lets Strands agents run async coroutines synchronously by binding them to the current or a new event loop.

