import logging
from strands_agents import SteeringHandler

class RiskBlockingSteeringHandler(SteeringHandler):
    """
    Steering Handler for strands-agents v1.30 that blocks risky tools
    before they run by implementing steer_before_tool.
    """
    RISKY_TOOLS = {'dangerous_tool', 'format_disk', 'shutdown_system'}

    def __init__(self, *args, **kwargs):
        super(RiskBlockingSteeringHandler, self).__init__(*args, **kwargs)

    def steer_before_tool(self, tool, *args, **kwargs):
        # Normalize tool name
        name = None
        if hasattr(tool, 'name'):
            name = getattr(tool, 'name')
        if name is None:
            name = tool
        if isinstance(name, (list, tuple)):
            name = name[0] if len(name) > 0 else str(tool)

        tool_name = str(name)

        if tool_name in self.RISKY_TOOLS:
            logging.getLogger(__name__).warning("Blocking risky tool before run: %s", tool_name)
            return False  # Block execution

        return True  # Allow execution

Note: This uses steer_before_tool (the v1.30 override) to block risky tools before they run. Customize RISKY_TOOLS with the actual tool names you want to block.

