    - dangerous_tools: iterable of tool names to block
    - safe_redirect: mapping from dangerous tool name -> safe alternative tool name
    - Return value is a directive understood by your runtime; adjust keys if your
      version expects a different contract.
    """

    def __init__(self, dangerous_tools=None, safe_redirect=None, logger=None):
        super().__init__()
        self.dangerous_tools = set(dangerous_tools or {"dangerous_tool"})
        self.safe_redirect = dict(safe_redirect or {})  # {tool_name: alternative_tool_name}
        self.logger = logger or logging.getLogger(__name__)

    def steer_before_tool(self, tool_name, tool_args, context=None):
        """
        Called before executing a tool. Decide whether to allow, block, or redirect.

        Expected return (example):
            {"action": "allow"}
            {"action": "block"}
            {"action": "redirect", "tool_name": "safe_tool", "tool_args": {...}}

        Adjust the return shape to match your Strands Agents runtime if needed.
        """
        if tool_name in self.dangerous_tools:
            self.logger.warning("Steering away from dangerous tool: %s", tool_name)

            if tool_name in self.safe_redirect:
                alt = self.safe_redirect[tool_name]
                self.logger.info("Redirecting to safe tool: %s", alt)
                return {"action": "redirect", "tool_name": alt, "tool_args": tool_args}

            # No safe alternative configured; block usage of the dangerous tool.
            return {"action": "block"}

        # Not a dangerous tool; allow normal execution
        return {"action": "allow"}


