from typing import Optional, Any

class DangerSteeringHandler(SteeringHandler):
    """
    Steering handler compatible with strands-agents 1.30.
    Overrides steer_before_tool to steer away from dangerous tools.

    Note:
    - In 1.30, the override name is steer_before_tool (not steer).
    - Implementing this method allows you to return a modified prompt
      to prevent the model from calling a dangerous tool.
    - Adjust the DANGEROUS_TOOLS set to fit your safety policy.
    """

    DANGEROUS_TOOLS = {
        "delete_all_files",
        "shutdown_server",
        "format_disk",
        "dangerous_tool",
    }

    def _tool_name(self, tool: Any) -> str:
        if isinstance(tool, dict):
            return str(tool.get("name", ""))
        return getattr(tool, "name", None) or str(tool)

    def steer_before_tool(self, *args, **kwargs) -> Optional[str]:
        """
        Potential signatures:
        - steer_before_tool(self, tool, prompt)
        - steer_before_tool(self, prompt, tool)
        - steer_before_tool(self, tool, prompt, extra_context=...)
        - steer_before_tool(self, prompt)  # if no tool provided
        This method is robust to different call orders to maximize compatibility.

        Returns:
        - A modified prompt string to steer away from calling the tool, or
        - None to allow the tool call to proceed.
        """
        tool = None
        prompt = None

        # Heuristic parsing of common signature orders
        if len(args) >= 2:
            tool, prompt = args[0], args[1]
        elif len(args) == 1:
            if isinstance(args[0], (str, dict)):
                prompt = args[0]
            else:
                tool = args[0]

        # Override from kwargs if provided
        if "tool" in kwargs:
            tool = kwargs["tool"]
        if "prompt" in kwargs:
            prompt = kwargs["prompt"]

        if tool is None or prompt is None:
            # Not enough context to steer; let the tool call proceed
            return None

        name = self._tool_name(tool)
        if name in self.DANGEROUS_TOOLS:
            return (
                f"{prompt}\n\n"
                f"Note: The tool '{name}' is restricted due to safety concerns. "
                f"Please avoid using it and propose a safe alternative."
            )

        return None

