        """
        Inspect the steering request and block any action that uses a risky tool.
        Returns True to allow, False to block.
        Handles both dict-like and object-like steering_request shapes.
        """
        actions = []
        if isinstance(steering_request, dict):
            actions = steering_request.get("planned_actions", steering_request.get("actions", []))
        else:
            actions = getattr(steering_request, "planned_actions", [])

        for action in actions:
            tool = None
            if isinstance(action, dict):
                tool = action.get("tool")
            else:
                tool = getattr(action, "tool", None)

            if tool in self._risky_tools:
                # Block by signaling block in the steering request
                if isinstance(steering_request, dict):
                    steering_request["blocked_actions"] = steering_request.get("blocked_actions", []) + [action]
                    steering_request["decision"] = "block"
                else:
                    setattr(steering_request, "decision", "block")
                return False
        return True

    def on_steer(self, steering_request):
        # Compatibility hook; delegate to steer
        return self.steer(steering_request)

