import sys
import json
import requests

def extract_tool_name(obj):
    if isinstance(obj, dict):
        if 'tool' in obj and isinstance(obj['tool'], dict):
            t = obj['tool']
            if 'name' in t and isinstance(t['name'], str):
                return t['name']
            if 'tool_name' in t and isinstance(t['tool_name'], str):
                return t['tool_name']
        if 'name' in obj and isinstance(obj['name'], str):
            return obj['name']
        if 'tool_name' in obj and isinstance(obj['tool_name'], str):
            return obj['tool_name']
        for v in obj.values():
            res = extract_tool_name(v)
            if res:
                return res
    elif isinstance(obj, list):
        for item in obj:
            res = extract_tool_name(item)
            if res:
                return res
    return None

def parse_sse(url, token=None):
    headers = {}
    if token:
        headers['Authorization'] = f'Bearer {token}'
    with requests.get(url, stream=True, headers=headers) as resp:
        resp.raise_for_status()
        event_name = None
        data_parts = []
        for line in resp.iter_lines(decode_unicode=True):
            if line == '':
                if event_name is not None:
                    payload = '\n'.join(data_parts)
                    data_parts = []
                    yield event_name, payload
                    event_name = None
                continue
            if line.startswith('event:'):
                event_name = line[len('event:'):].strip()
            elif line.startswith('data:'):
                data_parts.append(line[len('data:'):].lstrip())
            else:
                pass
        if event_name is not None:
            payload = '\n'.join(data_parts)
            yield event_name, payload

def main():
    if len(sys.argv) < 2:
        print("Usage: python agui_sse_tool.py <sse_url> [token]")
        sys.exit(2)
    url = sys.argv[1]
    token = sys.argv[2] if len(sys.argv) > 2 else None
    for event_name, payload in parse_sse(url, token):
        if event_name == 'TOOL_CALL_START':
            try:
                data = json.loads(payload)
            except Exception:
                continue
            tool_name = extract_tool_name(data)
            if tool_name:
                print(tool_name)
            else:
                print('[TOOL_CALL_START] tool name not found')

if __name__ == '__main__':
    main()

