def ensure_s3_vectors_index_exists(index_name, role_arn, region_name=None, edition='DEVELOPER', description=None):
    """
    Ensure an AWS Kendra S3 Vector index exists. If not found, create it.
    Assumes the S3 Vector index is exposed via Kendra vector indexing.
    """
    kendra = boto3.client('kendra', region_name=region_name)

