from typing import List, Tuple, Dict, Any, Optional, Union

def _extract_messages_from_source(src: Any) -> List[Dict[str, Any]]:
    if isinstance(src, list):
        return src
    if isinstance(src, dict):
        if 'messages' in src and isinstance(src['messages'], list):
            return src['messages']
        if 'dialog' in src and isinstance(src['dialog'], dict):
            d = src['dialog']
            if 'messages' in d and isinstance(d['messages'], list):
                return d['messages']
        if 'turns' in src and isinstance(src['turns'], list):
            return src['turns']
    return []

def _normalize_message(m: Dict[str, Any]) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    # returns (role, text, ts)
    role = None
    text = None
    ts = None
    if not isinstance(m, dict):
        return (role, text, ts)
    ts = m.get('timestamp') or m.get('time')
    text = m.get('text') or m.get('content') or m.get('message')
    role = m.get('role') or m.get('speaker') or m.get('who') or m.get('side')
    if text is None:
        payload = m.get('payload')
        if isinstance(payload, dict):
            role = role or payload.get('role') or payload.get('speaker')
            if text is None:
                text = payload.get('text') or payload.get('content') or payload.get('message')
    return role, text, ts

def split_session_turns(session_or_path: Union[str, Any]) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """
    Walk a Strands session and split messages into user_turns and assistant_turns.

    Accepts:
      - a path to a JSON file containing a Strands session
      - a Python object (e.g., session) with attributes 'messages', 'turns', or 'dialog'
        that contain a list of message dicts

    Returns:
      (user_turns, assistant_turns) where each is a list of dicts with keys:
      'timestamp' (optional), 'text', and 'raw' (optional original message)
    """
    messages: List[Dict[str, Any]] = []
    if isinstance(session_or_path, str):
        import json
        with open(session_or_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        messages = _extract_messages_from_source(data)
    else:
        src = session_or_path
        for attr in ('messages', 'turns', 'dialog'):
            if hasattr(src, attr):
                messages = _extract_messages_from_source(getattr(src, attr))
                if messages:
                    break
        if not messages:
            to_json = getattr(src, 'to_json', None)
            if callable(to_json):
                messages = _extract_messages_from_source(to_json())
        if not messages and isinstance(src, list):
            messages = src

    user_turns: List[Dict[str, Any]] = []
    assistant_turns: List[Dict[str, Any]] = []

    for m in messages:
        role, text, ts = _normalize_message(m)
        if text is None:
            continue
        item = {'timestamp': ts, 'text': text, 'raw': m}
        if isinstance(role, str):
            r = role.lower()
            if 'user' in r:
                user_turns.append(item)
            elif 'assistant' in r or 'bot' in r or 'agent' in r:
                assistant_turns.append(item)
            else:
                # unknown role; ignore or handle as needed
                pass
        else:
            # no explicit role; ignore or implement fallback
            pass

    return user_turns, assistant_turns

