def _iter_session_turns(session):
    """
    Yield individual turn/message objects from a Strands session.
    Tries common shapes: session.messages, session.turns, session.events,
    or a dict with a 'messages'/'turns'/'events' key. Falls back to iterating
    the session itself if possible.
    """
    if hasattr(session, 'messages'):
        for t in session.messages:
            yield t
        return

    if isinstance(session, dict):
        for key in ('messages', 'turns', 'events'):
            if key in session:
                for t in session[key]:
                    yield t
                return

    if hasattr(session, 'turns'):
        for t in session.turns:
            yield t
        return

    if hasattr(session, 'events'):
        for t in session.events:
            yield t
        return

    if isinstance(session, list):
        for t in session:
            yield t
        return

    # Fallback: try to iterate over session directly
    try:
        for t in session:
            yield t
    except TypeError:
        pass


def split_user_assistant_turns(session):
    """
    Walk a Strands session and separate user turns from assistant turns.

    Returns:
        user_turns: list of turn objects/messages deemed to be from the user
        assistant_turns: list of turn objects/messages deemed to be from the assistant
    Notes:
        - This is heuristic and handles common shapes where a turn has fields like:
          'sender', 'from', or 'role', and text payloads like 'text' or 'content'.
        - If speaker can't be determined, turns are assigned by alternation.
    """
    user_turns = []
    assistant_turns = []

    for t in _iter_session_turns(session):
        # Determine speaker
        speaker = None
        if hasattr(t, 'sender'):
            speaker = getattr(t, 'sender')
        if speaker is None and isinstance(t, dict):
            speaker = t.get('sender') or t.get('from') or t.get('role')
        if speaker is None:
            speaker = getattr(t, 'from_', None) or getattr(t, 'role', None)

        s = str(speaker).lower() if speaker is not None else ''

        # Attempt to extract content to ensure it's a turn with text
        content = None
        if isinstance(t, dict):
            content = t.get('text') or t.get('content') or t.get('payload')
        else:
            content = getattr(t, 'text', None) or getattr(t, 'content', None) or getattr(t, 'payload', None)
        if content is None:
            # Skip entries without textual content
            continue

        if s in ('user', 'customer', 'human', 'you'):
            user_turns.append(t)
        elif s in ('assistant', 'agent', 'bot', 'system'):
            assistant_turns.append(t)
        else:
            # Fallback: alternate based on counts to avoid bias
            if len(user_turns) <= len(assistant_turns):
                user_turns.append(t)
            else:
                assistant_turns.append(t)

    return user_turns, assistant_turns


