def split_session_user_assistant(session):
    """
    Walk messages in a Strands session and split into user turns and assistant turns.
    Returns a tuple: (user_turns, assistant_turns) where each is a list of strings.
    This function is resilient to common message shapes (dicts or objects) and common
    field names in Strands sessions.
    """
    user_turns = []
    assistant_turns = []

    # Gather messages from common attributes
    messages = []
    for attr in ('messages', 'history', 'turns'):
        if hasattr(session, attr):
            val = getattr(session, attr)
            if isinstance(val, (list, tuple)):
                messages = list(val)
            else:
                try:
                    messages = list(val)
                except Exception:
                    messages = []
            if messages:
                break

    if not messages:
        return user_turns, assistant_turns

    current_role = None  # 'user' or 'assistant'
    current_texts = []

    def flush():
        nonlocal current_role, current_texts
        if not current_role:
            return
        text = ' '.join([t for t in current_texts if isinstance(t, str)])
        if current_role == 'user':
            user_turns.append(text.strip())
        elif current_role == 'assistant':
            assistant_turns.append(text.strip())
        current_role = None
        current_texts = []

    for m in messages:
        role = None
        text = None

        # dict-like message
        if isinstance(m, dict):
            role = m.get('role') or m.get('sender') or m.get('from')
            text = m.get('text') or m.get('content') or m.get('payload')
        else:
            # object-like message
            if hasattr(m, 'role'):
                role = getattr(m, 'role')
            if hasattr(m, 'sender') and role is None:
                role = getattr(m, 'sender')
            if hasattr(m, 'text'):
                text = getattr(m, 'text')
            elif hasattr(m, 'content'):
                text = getattr(m, 'content')

        if text is None:
            if hasattr(m, 'message') and isinstance(m.message, str):
                text = m.message

        if isinstance(text, list):
            text = ' '.join([t for t in text if isinstance(t, str)])

        # Normalize role
        rl = None
        if isinstance(role, str):
            r = role.lower()
            if r in ('user', 'customer', 'human'):
                rl = 'user'
            elif r in ('assistant', 'bot', 'ai', 'system'):
                rl = 'assistant'

        # Heuristic from text if role not clear
        if rl is None and isinstance(text, str):
            t = text.strip().lower()
            if t.startswith('user:'):
                text = t[5:].strip()
                rl = 'user'
            elif t.startswith('assistant:') or t.startswith('ai:') or t.startswith('bot:'):
                text = t.split(':', 1)[1].strip()
                rl = 'assistant'

        if rl is None:
            # If we can't determine, keep current speaker
            if current_role is None:
                continue
            rl = current_role

        if text is None:
            text = ''

        if rl != current_role:
            flush()
            current_role = rl

        current_texts.append(text)

    flush()
    return user_turns, assistant_turns

Note: This helper is robust to variations in Strands message shapes. If your session uses nonstandard field names, adjust the role/text extraction logic accordingly.

def split_session_turns(session):
    # Helper to iterate messages from the session, supporting common APIs
    def iter_messages(sess):
        if getattr(sess, "messages", None) is not None:
            for m in sess.messages:
                yield m
        elif callable(getattr(sess, "get_messages", None)):
            for m in sess.get_messages():
                yield m
        else:
            return

    # Normalize speaker and text from a message (handles both dict-like and object-like msgs)
    def speaker_text(m):
        if isinstance(m, dict):
            speaker = m.get("speaker") or m.get("role") or m.get("from")
            text = m.get("text") or m.get("content") or ""
        else:
            speaker = getattr(m, "speaker", None) or getattr(m, "role", None) or getattr(m, "from_", None)
            text = getattr(m, "text", None) or getattr(m, "content", None) or ""
        return speaker, text

    user_turns = []
    assistant_turns = []

    for idx, m in enumerate(iter_messages(session)):
        speaker, text = speaker_text(m)
        if not text:
            continue
        if speaker in ("user", "customer", "human"):
            user_turns.append({"index": idx, "text": text, "raw": m})
        elif speaker in ("assistant", "bot", "agent"):
            assistant_turns.append({"index": idx, "text": text, "raw": m})
        else:
            # Unknown speaker; skip or handle separately if needed
            pass

    return user_turns, assistant_turns

