def report_token_usage(result):
    m = getattr(result, 'metrics', None)
    if not m:
        print("No metrics in result")
        return

    try:
        cycles = m.latest_agent_invocation.cycles
        if not cycles:
            print("No cycles in latest_agent_invocation")
            return
        usage = cycles[-1].usage  # Usage TypedDict
    except AttributeError:
        print("Metrics structure unexpected")
        return

    token_count = None
    if isinstance(usage, dict):
        if 'total_tokens' in usage:
            token_count = usage['total_tokens']
        elif 'tokens' in usage:
            token_count = usage['tokens']
        else:
            numeric = [v for v in usage.values() if isinstance(v, (int, float))]
            if numeric:
                token_count = sum(numeric)

    print(f"Latest invocation token usage: {token_count if token_count is not None else usage}")

def report_accumulated(result):
    acc = getattr(result.metrics, 'accumulated_usage', None)
    print(f"Accumulated tokens across invocations: {acc}")

