def extract_token_usage(res: object) -> int:
    def take_from_dict(d, keys):
        for k in keys:
            if k in d and isinstance(d[k], int):
                return int(d[k])
        return 0

    # If result is a dict
    if isinstance(res, dict):
        usage = res.get("usage") or res.get("token_usage") or res.get("tokens_used")
        if isinstance(usage, dict):
            t = take_from_dict(usage, ["total_tokens", "tokens"])
            if t:
                return t
        if "tokens" in res and isinstance(res["tokens"], int):
            return int(res["tokens"])

    # If result is an object with attributes
    if hasattr(res, "usage"):
        u = getattr(res, "usage")
        if isinstance(u, dict):
            t = take_from_dict(u, ["total_tokens", "tokens"])
            if t:
                return t
        if isinstance(u, int):
            return int(u)
    if hasattr(res, "token_count"):
        t = getattr(res, "token_count")
        if isinstance(t, int):
            return int(t)

    return 0

